import {mapStartMinutes,formatClock,timeOfDay} from './game-clock.js';
import {installLibrary} from './editor-3d-library.js';
import {GROUNDS,PROPS,EDGES} from './core/environment.js';
import {SPECIES,WEAPON_IDS,blankMap} from './core/maps.js';
import {brushPoint} from './editor-3d-controller.js';
import {listDesigns,getDesign,saveDesign} from './editor-3d-store.js';
import {launchPlaytest} from './editor-playtest.js';
export function installEditing({canvas,scene,getDocument,getSelection,open,changed,status,isLoading,switchWorkspace,hasUnsaved}){
 const $=id=>document.getElementById(id),panel=document.createElement('section');panel.id='editing-tools';
 panel.innerHTML=`<h2>Build</h2><label>Tool<select id="edit-tool"></select></label><p id="foliage-help" class="muted" hidden>Drag a rectangle to paint dark-green, traversable concealment. Deeper foliage hides people more strongly; it is not bullet protection. Water, buildings and props are skipped. Clear foliage restores ordinary grass.</p><label>Terrain<select id="ground-kind"></select></label><label>Prop<select id="prop-kind"></select></label><label>Light schedule<select id="light-mode"><option value="auto">Automatic · lamps at night, fires always</option><option value="on">Always on</option><option value="off">Off / extinguished</option></select></label><button id="apply-light-mode">Apply to selected light</button><button id="aim-spotlight">Pick spotlight aim points</button><button id="finish-spotlight" hidden>Save aim points</button><p class="muted">Select a spotlight, then pick 1–3 map tiles in order. One holds steady; multiple points sweep in a loop, taking one game minute per leg. Save after 1 or 2 points, or pick 3 to finish. Escape cancels.</p><p class="muted">Light reaches 5 tiles at full strength, then halves every 5 tiles. Wall fixtures mount at the north edge; rotated fixtures mount at the east edge.</p><label>Boundary<select id="edge-kind"></select></label><div class="row"><label>Room width<input id="room-width" type="number" min="2" max="24" value="6"></label><label>Depth<input id="room-height" type="number" min="2" max="24" value="5"></label></div><label class="check"><input type="checkbox" id="rotated">Rotate placement 90°</label><details><summary>Guard / squad placement</summary><label>Species<select id="unit-species"></select></label><label>Weapon<select id="unit-weapon"></select></label><label>Outfit<select id="unit-outfit"><option value="normal">Normal</option><option value="red-hats">Red Hats</option></select></label><label>Facing (degrees)<input id="unit-heading" type="number" min="0" max="359" value="225"></label><label>Squad slot<select id="unit-slot"><option value="0">1</option><option value="1">2</option><option value="2">3</option><option value="3">4</option></select></label></details><div class="row"><button id="undo">Undo</button><button id="redo">Redo</button></div><div class="row"><button id="rotate-selected">Rotate selected</button><button id="delete-selected">Delete selected</button></div><button id="use-selected">Copy selected settings</button><p class="muted">Select / pan: drag camera. Build tools: drag a stroke, release to place. Right-drag to pan. Escape cancels. R rotates the preview.</p>`;
 document.querySelector('.tools').insertBefore(panel,document.querySelector('.tools h2'));
 const save=document.createElement('section');save.innerHTML=`<h2>Design</h2><label>Name<input id="design-name" maxlength="60"></label><div class="row"><button id="new-map">New map</button><button id="rename-map">Rename</button></div><div class="row"><button id="save-map">Save</button><button id="save-copy">Save copy</button></div><label>Saved designs<select id="saved-designs"></select></label><button id="load-map">Load selected</button><div class="row"><button id="validate-map">Validate</button><button id="playtest">Playtest ↗</button></div><label>Start time<input id="start-time" type="time" value="08:00"></label><button id="apply-start-time">Apply start time</button><p class="muted">Exploration: 1 game minute per 3 real seconds. Combat: 1 minute per completed round.</p><label>Preview daylight<input id="light-preview" type="range" min="0" max="1439" step="1" value="480"></label><output id="light-preview-label"></output><button id="light-preview-reset">Use map start time</button><p class="muted">Preview only. East is +X; west is −X. Apply start time above to change when play begins.</p><p id="validation" role="status"></p>`;document.querySelector('.properties').prepend(save);
 const add=(id,items)=>{for(const [value,label]of items)$(id).add(new Option(label,value));};
 add('edit-tool',[['inspect','Select / pan'],['texture','Paint terrain'],['floor','Paint floor'],['water','Water'],['bridge','Bridge'],['foliage-cover','Foliage cover'],['clear-foliage','Clear foliage'],['wall','Wall / fence'],['door','Door opening'],['room','Room'],['prop','Prop'],['roof-tile','Roof tiles'],['guard','Guard'],['squad','Squad start'],['exit','Travel marker'],['stairs','Stairs'],['ladder','Ladder'],['roof','Roof climb'],['erase-prop','Erase prop'],['remove-guard','Erase guard'],['erase-edge','Erase boundary'],['erase-tile','Erase terrain'],['erase-stairs','Erase stairs'],['erase-roof','Erase climb']]);
 for(const [id,items]of [['ground-kind',GROUNDS],['prop-kind',Object.keys(PROPS)],['edge-kind',Object.keys(EDGES)],['unit-species',SPECIES],['unit-weapon',WEAPON_IDS]])add(id,items.map(x=>[x,x]));
 $('unit-species').value='pig-foreman';$('unit-weapon').value='pistol';
 let aiming=null,stroke=null,lastPreview='',recordId=null,busy=false,request=0,pending=null;
 const options=()=>({groundKind:$('ground-kind').value,propKind:$('prop-kind').value,lightMode:$('light-mode').value,edgeKind:$('edge-kind').value,width:+$('room-width').value,height:+$('room-height').value,rotated:$('rotated').checked,species:$('unit-species').value,weapon:$('unit-weapon').value,outfit:$('unit-outfit').value,heading:+$('unit-heading').value,slot:+$('unit-slot').value});
 const point=e=>{const b=canvas.getBoundingClientRect(),p=scene.pick(e.clientX-b.left,e.clientY-b.top,b.width,b.height);return p&&brushPoint(p);};
 const command=p=>({tool:$('edit-tool').value,start:stroke||p,end:p,options:options()});
 function preview(p){if(!p)return;const c=command(p),key=JSON.stringify(c);if(key===lastPreview)return;lastPreview=key;const r=getDocument().preview(c);scene.preview(r);status(r.ok?(r.cells.length+' tiles · Release to place · Escape cancels'):r.error);}
 const cancel=()=>{aiming=null;$('finish-spotlight').hidden=true;stroke=null;pending=null;lastPreview='';scene.preview(null);};
 async function apply(c){if(busy||isLoading())return {ok:false,error:'Wait for the scene to finish loading.'};const result=getDocument().apply(c);if(result.ok){busy=true;cancel();try{await changed();sync();status('Edit applied.');}finally{busy=false;}}else status(result.error);return result;}
 async function finishAim(){if(!aiming?.points.length)return status('Pick at least one tile.');const {selection,points}=aiming;await run(()=>getDocument().lightTargets(selection,points),'Spotlight aim points saved.');}
 $('aim-spotlight').onclick=()=>{if(busy||isLoading())return;const selection=getSelection();if(selection?.type!=='prop'||selection.data.kind!=='spotlight')return status('Use Select / pan to select a spotlight first.');cancel();aiming={selection,points:[]};$('finish-spotlight').hidden=false;status('Click 1–3 aim tiles, then Save aim points. Escape cancels.');};
 $('finish-spotlight').onclick=finishAim;
 canvas.addEventListener('pointerdown',e=>{if(!aiming||e.button!==0)return;e.stopImmediatePropagation();canvas.setPointerCapture(e.pointerId);canvas.focus();},true);
 canvas.addEventListener('pointermove',e=>{if(aiming&&e.buttons!==2)e.stopImmediatePropagation();},true);
 canvas.addEventListener('pointerup',e=>{if(!aiming||e.button!==0)return;e.stopImmediatePropagation();const p=point(e);if(!p)return;const size=getDocument().size;if(p.x<0||p.y<0||p.x>=size||p.y>=size)return status('Choose a tile inside the map.');if(aiming.points.some(q=>q.x===p.x&&q.y===p.y&&q.z===p.z))return status('Choose a different tile.');aiming.points.push(p);scene.preview({ok:true,cells:aiming.points});status(aiming.points.length+' aim points · Save or pick another tile');if(aiming.points.length===3)finishAim();},true);
 canvas.addEventListener('contextmenu',e=>e.preventDefault());
 canvas.addEventListener('pointerdown',e=>{if(e.button!==0||$('edit-tool').value==='inspect')return;e.stopImmediatePropagation();if(busy||isLoading())return;stroke=point(e);canvas.setPointerCapture(e.pointerId);canvas.focus();lastPreview='';preview(stroke);},true);
 canvas.addEventListener('pointermove',e=>{if($('edit-tool').value==='inspect'||e.buttons===2||busy||isLoading())return;e.stopImmediatePropagation();pending=point(e);if(!request)request=requestAnimationFrame(()=>{request=0;if(pending)preview(pending);pending=null;});},true);
 canvas.addEventListener('pointerup',e=>{if(e.button!==0||!stroke)return;e.stopImmediatePropagation();const end=point(e);const c=command(end||stroke);cancel();apply(c);},true);
 canvas.addEventListener('pointercancel',cancel,true);canvas.addEventListener('pointerleave',()=>{if(!stroke&&!aiming)cancel();});
 function controls(){const tool=$('edit-tool').value;$('foliage-help').hidden=!['foliage-cover','clear-foliage'].includes(tool);for(const [id,visible]of [['ground-kind',tool==='texture'],['prop-kind',['prop','roof-tile'].includes(tool)],['edge-kind',tool==='wall'],['rotated',['prop','roof-tile','room'].includes(tool)]])$(id).closest('label').hidden=!visible;$('room-width').closest('.row').hidden=tool!=='room';const detail=$('unit-species').closest('details');detail.hidden=!['guard','squad'].includes(tool);detail.open=true;}
 $('edit-tool').onchange=()=>{cancel();controls();};controls();for(const e of panel.querySelectorAll('select,input'))e.addEventListener('change',()=>{lastPreview='';if(stroke)preview(stroke);});
 async function history(direction){if(busy||isLoading())return;cancel();if(getDocument()[direction]()){busy=true;try{await changed();sync();status(direction==='undo'?'Undone.':'Redone.');}finally{busy=false;}}}
 $('undo').onclick=()=>history('undo');$('redo').onclick=()=>history('redo');
 $('delete-selected').onclick=()=>{const s=getSelection();if(!s)return status('Select an object first.');const tool=s.type==='prop'?'erase-prop':s.type==='edge'?'erase-edge':s.type==='unit'&&s.data.id.startsWith('guard')?'remove-guard':s.type==='tile'?'erase-tile':null;if(!tool)return status('Squad starts and travel markers must be repositioned with their placement tools.');apply({tool,start:{x:s.x,y:s.y,z:s.z,edge:s.edge},options:{}});};
 $('rotate-selected').onclick=async()=>{if(busy||isLoading())return;const r=getDocument().rotate(getSelection());if(!r.ok)return status(r.error);busy=true;try{await changed();sync();}finally{busy=false;}};
 $('use-selected').onclick=()=>{const s=getSelection();if(s?.type==='prop'){$('prop-kind').value=s.data.kind;$('light-mode').value=s.data.lightMode||'auto';$('rotated').checked=!!s.data.rotated;$('edit-tool').value='prop';}else if(s?.type==='unit'&&s.data.id.startsWith('guard')){for(const [id,key]of [['unit-species','species'],['unit-weapon','weapon'],['unit-outfit','outfit'],['unit-heading','heading']])$(id).value=s.data[key]??(key==='outfit'?'normal':225);$('edit-tool').value='guard';}else status('Select a prop or guard.');cancel();controls();};
 document.addEventListener('keydown',e=>{if(e.target.closest?.('input,textarea,select')||e.target.isContentEditable)return;if(e.key==='Escape'){cancel();e.preventDefault();}else if(e.key.toLowerCase()==='r'&&!e.ctrlKey&&!e.metaKey){$('rotated').checked=!$('rotated').checked;lastPreview='';if(stroke)preview(stroke);e.preventDefault();}else if((e.ctrlKey||e.metaKey)&&['z','y'].includes(e.key.toLowerCase())){e.preventDefault();history(e.key.toLowerCase()==='y'||e.shiftKey?'redo':'undo');}});
 const guardReplace=()=>{if(busy||isLoading()){status('Wait for the scene update to finish.');return false;}return !hasUnsaved()||confirm('A workspace has unsaved changes. Continue replacing a design?');};
 $('new-map').onclick=async()=>{if(!guardReplace())return;recordId=null;await open(JSON.stringify(blankMap('New design')));};
 $('rename-map').onclick=async()=>{if(busy||isLoading())return;const r=getDocument().rename($('design-name').value);if(r.ok){busy=true;try{await changed();sync();}finally{busy=false;}}else status(r.error);};
 async function refreshSaves(){const selected=$('saved-designs').value,records=await listDesigns();$('saved-designs').replaceChildren(...records.sort((a,b)=>b.updated-a.updated).map(r=>new Option((JSON.parse(r.json).kind==='red-shift-block'?'Block · ':'Map · ')+r.name,r.id)));if(records.some(r=>r.id===selected))$('saved-designs').value=selected;}
 async function saveMap(copy){if(busy||isLoading())return status('Wait for the current operation to finish.');busy=true;try{const doc=getDocument(),name=$('design-name').value.trim();if(name!==doc.map.name){const r=doc.rename(name);if(!r.ok)throw Error(r.error);await changed();}const id=copy||!recordId?crypto.randomUUID():recordId,revision=doc.revision;await saveDesign({id,name:doc.map.name,json:doc.export(),updated:Date.now(),version:1});recordId=id;doc.libraryId=id;if(doc.revision===revision)doc.changed=false;await refreshSaves();$('saved-designs').value=id;sync();status('Saved in this browser. Export JSON for a portable backup.');}catch(e){status('Save failed: '+e.message);}finally{busy=false;}}
 $('save-map').onclick=()=>saveMap(false);$('save-copy').onclick=()=>saveMap(true);
 $('load-map').onclick=async()=>{if(!guardReplace())return;busy=true;try{const r=await getDesign($('saved-designs').value);if(!r)throw Error('Choose a saved design.');await open(r.json);recordId=r.id;getDocument().libraryId=r.id;}catch(e){status('Load failed: '+e.message);}finally{busy=false;}};
 const validate=()=>{const errors=getDocument().validate();$('validation').textContent=errors.length?errors.slice(0,8).join('\n'):getDocument().block?'Valid block - save it, then place it in a full map.':'Valid map — ready to playtest.';return errors;};
 $('validate-map').onclick=validate;$('playtest').onclick=()=>{try{if(busy||isLoading())return status('Wait for the current operation to finish.');if(getDocument().block)return status('Place the block in a full map to playtest.');if(validate().length)return;launchPlaytest(getDocument().export());status('Playtest opened. Your blueprint and undo history stay here.');}catch(e){status(e.message);}};
 function previewLight(value){scene.previewMinutes=value;const minutes=value??mapStartMinutes(getDocument()?.map);$('light-preview').value=minutes;$('light-preview-label').textContent=formatClock({minutes})+' · '+timeOfDay({minutes}).phase;scene.changed();}
 $('light-preview').oninput=()=>previewLight(+$('light-preview').value);$('light-preview-reset').onclick=()=>previewLight(null);
 function sync(){const d=getDocument();if(!d)return;$('design-name').value=d.map.name;$('undo').disabled=!d.editor?.undo.length;$('redo').disabled=!d.editor?.redo.length;$('playtest').disabled=!!d.block;$('validation').textContent='';const start=mapStartMinutes(d.map);$('start-time').value=String(Math.floor(start/60)).padStart(2,'0')+':'+String(start%60).padStart(2,'0');$('start-time').disabled=$('apply-start-time').disabled=d.block;previewLight(scene.previewMinutes);library.sync();}
 async function run(operation,message,update=true){if(busy||isLoading())return status('Wait for the current operation to finish.');busy=true;cancel();try{await operation();if(update)await changed();sync();status(message);}catch(e){status(e.message);}finally{busy=false;}}
 $('apply-light-mode').onclick=()=>run(()=>getDocument().lightMode(getSelection(),$('light-mode').value),'Light schedule updated.');
 $('apply-start-time').onclick=()=>run(()=>{const value=$('start-time').value;if(!/^\d{2}:\d{2}$/.test(value))throw Error('Choose a start time.');const [hours,minutes]=value.split(':').map(Number);getDocument().startTime(hours*60+minutes);},'Start time updated. Playtest starts at this time.');
 const library=installLibrary({getDocument,run,open,guardReplace,refreshSaves,status,switchWorkspace:mode=>{if(busy||isLoading()){library.sync();return;}switchWorkspace(mode).catch(e=>status(e.message));}});
 refreshSaves().catch(e=>status('Browser saves unavailable: '+e.message));window.addEventListener('beforeunload',e=>{if(hasUnsaved()){e.preventDefault();e.returnValue='';}});
 return {sync,apply,reset(){cancel();scene.previewMinutes=null;recordId=getDocument().libraryId||null;sync();},guardReplace};
}
